// This will fail to compile: new T[10];

// The standard workaround using a raw array cast:
public class GenericArrayFactory<T> {
    private final T[] array;

    @SuppressWarnings("unchecked")
    public GenericArrayFactory(Class<T> clazz, int size) {
        // We create a raw array and cast it to T[]
        this.array = (T[]) java.lang.reflect.Array.newInstance(clazz, size);
    }
}
